import re
import time
import logging
from typing import Optional, Union
from paramiko.channel import Channel
from taf.transport.ssh.connection import SSHConnection
from taf.transport.ssh.exceptions import CommandOutputCollectionError


class AasyslogThroughPutConfiguration(object):

    def __init__(self, host: str, username: str, password: str, ccs_shell_type: Optional[str] = "mcu"):
        self._host = host
        self._username = username
        self._password = password
        self._ccs_shell_type = ccs_shell_type

    @staticmethod
    def _get_expected_config_output(aa_sys_mode: Union[str, int] = '2',
                                    aa_sys_addr: Optional[str] = '0x7F000001',
                                    aa_sys_udp_port: Optional[str] = '0xC738'):
        return [
            "[0x10041] 'AaSysLogOutputMode' = 0x{}".format(aa_sys_mode),
            "[0x10042] 'AaSysLogUdpAddress' = {}".format(aa_sys_addr),
            "[0x10043] 'AaSysLogUdpPort' = {}".format(aa_sys_udp_port),
        ]

    def _aasyslog_realtime_output_configuration(self,
                                                aa_sys_mode: str,
                                                aa_sys_addr: str,
                                                aa_sys_udp_port: str):
        if self._ccs_shell_type.lower() == "mcu":
            aasyslog_port = 15007
        elif self._ccs_shell_type.lower() == "rt":
            aasyslog_port = 35007
        else:
            raise ValueError("Wrong type: {}, should be MCU or RT".format(type))
        sshconnection = SSHConnection()
        sshconnection.configure(hostname=self._host, username=self._username, password=self._password, timeout=300)
        sshconnection.connect()
        logging.info("Start configure AaSysLog for realtime output")
        _cmd_kill_telnet = "ps -ef|grep telnet|grep " + str(
            aasyslog_port) + "|grep -v grep|awk '{print $2}'| xargs kill -9"
        sshconnection.send_command(_cmd_kill_telnet)
        tn = sshconnection.invoke_shell()
        tn.send('telnet 0 {}\n'.format(aasyslog_port))
        self._match_shell_til(tn, "AaShell>", 3)
        logging.info("Aashell created.")
        tn.send("rad -w 0x10041 {}\r".format(aa_sys_mode))
        self._match_shell_til(tn, "written succesfully", timeout=3)
        tn.send('rad -w 0x10042 {}\r'.format(aa_sys_addr))
        self._match_shell_til(tn, "written succesfully", timeout=3)
        tn.send('rad -w 0x10043 {}\r'.format(aa_sys_udp_port))
        self._match_shell_til(tn, "written succesfully", timeout=3)
        tn.send('rad -a\r')
        resp = self._match_shell_til(tn, "0x3F004F", timeout=10)
        logging.info("Commands sent in Aashell, checking result.")
        try:
            tn.send('quit\r')
            self._match_shell_til(tn, "Bye", timeout=3)
        except CommandOutputCollectionError:
            pass
        sshconnection.disconnect()
        logging.info("AaSysLog configuration done: {}".format(resp))
        for _exp in self._get_expected_config_output(aa_sys_mode=aa_sys_mode,
                                                     aa_sys_addr=aa_sys_addr,
                                                     aa_sys_udp_port=aa_sys_udp_port):
            if _exp not in resp:
                raise AssertionError("AaSysLog configuration failed, can't found expected output: {}".format(_exp))
        return resp

    def _match_shell_til(self,
                         shell: Channel,
                         match: str,
                         timeout: int):
        start = time.time()
        output = ""
        while (time.time() - start) <= timeout:
            output += str(shell.recv(65535))
            if re.search(match, output):
                return output
            time.sleep(0.1)
        else:
            raise TimeoutError("Match {} failed".format(match))

    def enable(self):
        """
        enable Aasyslog in aashell for real time output print.
        """
        aa_sys_mode = '2'
        aa_sys_addr = '0x7F000001'
        aa_sys_udp_port = '0xC738'

        resp = self._aasyslog_realtime_output_configuration(
            aa_sys_mode=aa_sys_mode,
            aa_sys_addr=aa_sys_addr,
            aa_sys_udp_port=aa_sys_udp_port)
        return resp

    def disable(self):
        """
        disable Aasyslog in aashell for real time output print.
        """
        aa_sys_mode = '5'
        aa_sys_addr = "0xC0A8FF7E"
        aa_sys_udp_port = "0xC738"

        resp = self._aasyslog_realtime_output_configuration(
            aa_sys_mode=aa_sys_mode,
            aa_sys_addr=aa_sys_addr,
            aa_sys_udp_port=aa_sys_udp_port)
        return resp
